import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/SoftMax.html","title":"SoftMax","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.67,"words":200},"filePathRelative":"SoftMax.md"}`),a={name:`SoftMax.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="softmax" tabindex="-1"><a class="header-anchor" href="#softmax"><span>SoftMax</span></a></h1><p>一般的には大文字ではなくsoftmaxと書くが、WikiName的に違和感があったのでWikiNameはSoftMaxとした。</p><h2 id="何をするものか" tabindex="-1"><a class="header-anchor" href="#何をするものか"><span>何をするものか</span></a></h2><p>n個の要素から、一番大きな要素の位置を1、それ以外を0で埋めたようなベクトルを返す。softなので完全な1と0じゃなくて一番大きいのが0.9,それ以外は0.1を分けるとかそんな感じになる。</p><p>なお、softmaxしたものと元のn個の要素の内積を取ると、一番大きい要素を取り出す演算となる。</p><p>微分が出来るのでback propagate出来て嬉しい。</p><p>伝統的にはカテゴリカルなモデルなどで、最後のフィーチャーをsoftmaxとって結果の確率とみなして学習する、みたいな使い方だったが、 昨今は<a href="./Transformer.html">Transformer</a>の流行の結果、<a href="./アテンション.html">アテンション</a>の文脈で良く登場するようになって、モデルの最後だけでなく途中のレイヤーでも頻繁に使われるようになった。</p><h2 id="具体例と定義" tabindex="-1"><a class="header-anchor" href="#具体例と定義"><span>具体例と定義</span></a></h2><p><img src="/RandomThoughts/assets/0000-CVskpF1M.png" alt="imgs/SoftMax/0000.png"></p><h2 id="演習3-5-softmaxが値の大きい所で誤差伝搬の勾配が小さくなるのを確認せよ-スケールの理由" tabindex="-1"><a class="header-anchor" href="#演習3-5-softmaxが値の大きい所で誤差伝搬の勾配が小さくなるのを確認せよ-スケールの理由"><span>演習3.5 softmaxが値の大きい所で誤差伝搬の勾配が小さくなるのを確認せよ（スケールの理由）</span></a></h2><p><a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a>の演習3.5。softmaxは入力の値の大きい領域では勾配が小さくなるという事を示したい。</p><p><img src="/RandomThoughts/assets/0001-B6o2bq5X.png" alt="imgs/Transformer/0001.png"><img src="/RandomThoughts/assets/0002-CnAGaqO8.png" alt="imgs/Transformer/0002.png"></p><p>こんな考察のもとに、<a href="./セルフアテンション.html">セルフアテンション</a>では、attentionに渡す値のスケールをdの影響分割り引く事にしているらしい。</p><p><a href="https://github.com/yoheikikuta/support-genAI-book/blob/main/exercises/chapter3.md#%E6%BC%94%E7%BF%92%E5%95%8F%E9%A1%8C35" target="_blank" rel="noopener noreferrer">support-genAI-book/exercises/chapter3.md at main · yoheikikuta/support-genAI-book</a> 菊田さんの解答。</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};